plugins {\n    java\n    id("io.micronaut.application") version "4.3.4"\n    id("io.micronaut.aot") version "4.3.4"\n    id("com.github.johnrengelman.shadow") version "8.1.1"\n}\n\nval micronautVersion = "4.3.4"\nval micronautBom = "3.9.7"\nval aotPluginVersion = "4.3.4"\nval shadowVersion = "8.1.1"\nval postgresDriverVersion = "42.5.1"\nval mongoDriverVersion = "4.10.2"\nval snakeyamlVersion = "2.0"\nval hikariVersion = "5.0.1"\n\ngroup = "com.ai2dev"\nversion = "0.1"\n\njava {\n    toolchain {\n        languageVersion.set(org.gradle.jvm.toolchain.JavaLanguageVersion.of(17))\n    }\n}\n\nmicronaut {\n    version("4.3.4")\n    runtime("netty")\n    testRuntime("junit5")\n    processing {\n        incremental(true)\n        annotations("com.ai2dev.testjava_wc.*")\n    }\n}\n\nrepositories {\n    mavenCentral()\n}\n\ndependencies {\n    // BOM import as required\n    implementation(platform("io.micronaut:micronaut-bom:${micronautBom}"))\n\n    // Core Micronaut runtime and server\n    implementation("io.micronaut:micronaut-runtime:${micronautVersion}")\n    implementation("io.micronaut:micronaut-http-server-netty:${micronautVersion}")\n    implementation("io.micronaut:micronaut-http-client:${micronautVersion}")\n    implementation("io.micronaut:micronaut-jackson-databind:${micronautVersion}")\n    implementation("io.micronaut:micronaut-validation:${micronautVersion}")\n\n    // Data backends and connectors with explicit versions\n    implementation("org.postgresql:postgresql:${postgresDriverVersion}")\n    implementation("org.mongodb:mongodb-driver-sync:${mongoDriverVersion}")\n    implementation("com.zaxxer:HikariCP:${hikariVersion}")\n\n    // SnakeYAML as requested\n    implementation("org.yaml:snakeyaml:${snakeyamlVersion}")\n\n    // Micronaut AOT support\n    implementation("io.micronaut.aot:micronaut-aot:${aotPluginVersion}")\n\n    // Logging\n    implementation("ch.qos.logback:logback-classic:1.4.11")\n}\n\napplication {\n    mainClass.set("com.ai2dev.testjava_wc.Application")\n}\n\ntasks.withType(org.gradle.jvm.tasks.Jar::class.java) {\n    manifest {\n        attributes("Main-Class" to "com.ai2dev.testjava_wc.Application")\n    }\n}\n\n// Shadow plugin configuration to create fat jar\ntasks.named("shadowJar") {\n    // default configuration is acceptable for this template\n}\n